                if line[i] == '"':
                    # Check if it's a doubled quote or the end of the field
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - represents one quote character
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None  # Malformed: closing quote not followed by comma or end
                        if i < len(line):
                            i += 1  # Skip the comma
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None  # Malformed: unterminated quoted field
            fields.append(field)
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    return None  # Malformed: unquoted field contains double quote
                field += line[i]
                i += 1
            fields.append(field)
            if i < len(line):
                i += 1  # Skip the comma

    return fields

